        { id: "2-19", word: "thorn", ipa: "/θɔːrn/", pos: "n.", definition: "A thorn is a sharp part of a plant.", example: "Be careful of the thorns when you pick the roses!", examples: ["A thorn stuck in my finger.", "Roses have sharp thorns."], vi: "cái gai", forms: ["thorns", "thorn"] },
        { id: "2-20", word: "wreck", ipa: "/rek/", pos: "v.", definition: "To wreck something means to destroy or ruin it.", example: "The teenagers wrecked the house for no reason at all.", examples: ["The storm wrecked the small boat.", "One mistake can wreck your plans."], vi: "phá hỏng, làm đắm", forms: ["wrecked", "wreck"] }
