        { id: "30-18", word: "typhoon", ipa: "/taɪˈfuːn/", pos: "n.", definition: "A typhoon is a large tropical storm that moves in circles.", example: "Thousands ofpeople lost electricity after a typhoon hit Australia.", examples: ["The typhoon brought heavy rain to the coast.", "Many flights were canceled because of the typhoon."], vi: "bão nhiệt đới", forms: ["typhoon"] },
        { id: "30-19", word: "wail", ipa: "/weɪl/", pos: "v.", definition: "To wail is to show sadness by crying loudly.", example: "The baby wailed because it was hungry.", examples: ["The baby wailed all night.", "She wailed when she heard the bad news."], vi: "than khóc, gào khóc", forms: ["wailed", "wail"] },
        { id: "30-20", word: "wardrobe", ipa: "/ˈwɔːrdroʊb/", pos: "n.", definition: "A wardrobe is the collection of all of a person’s clothing.", example: "She bought some new clothes to expand her wardrobe.", examples: ["He hung his coat in the wardrobe.", "She bought a new wardrobe for the summer."], vi: "tủ quần áo, bộ quần áo", forms: ["wardrobe"] }
